Method.Implementation:
  	$$$TRACE("Entering IHC.ITF.ITFCOMMON.Operation.FileOperationWithTransType...")
  	$$$TRACE("pRequest.TransType: "_pRequest.TransType)

	$$$TRACE("Append TransType to file path...")
	set origFilePath = ..Adapter.FilePath

	set ..Adapter.FilePath = ..Adapter.FilePath  _ pRequest.TransType _"/"

  	$$$TRACE("Adapter.FilePath: "_..Adapter.FilePath)

  	if ('##class(%File).DirectoryExists(..Adapter.FilePath))
  	{
	  	set tSC = ##class(%File).CreateDirectoryChain(..Adapter.FilePath)
	  	if ($$$ISERR(tSC))
	  	{
		  	set ..Adapter.FilePath = origFilePath
		  	return tSC
	  	}
  	}

  	set tSC=##super(pRequest,.pResponse)

  	set ..Adapter.FilePath = origFilePath


  	Quit tSC
